import re
class Solution:
    def betterCompression(self, compressed):
        cnt = [0] * 26
        for ch, num in re.findall(r'([a-z])(\d+)', compressed):
            cnt[ord(ch) - 97] += int(num)
        return ''.join(chr(97 + i) + str(cnt[i]) for i in range(26) if cnt[i])

