class Solution {
    public String betterCompression(String compressed) {
        long[] cnt = new long[26];
        java.util.regex.Matcher m = java.util.regex.Pattern.compile("([a-z])(\\d+)").matcher(compressed);
        while (m.find()) cnt[m.group(1).charAt(0) - 'a'] += Long.parseLong(m.group(2));
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < 26; i++)
            if (cnt[i] > 0) sb.append((char)('a' + i)).append(cnt[i]);
        return sb.toString();
    }
}

